// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint128 call1Blocknumber, uint128 call1Timestamp, uint128 call2Blocknumber, uint128 call2Timestamp) public {
        vm.assume(call1Timestamp > 0);
        vm.assume(call2Timestamp > call1Timestamp);
        vm.assume(call2Blocknumber != call1Blocknumber);
        call1Blocknumber = uint128(bound(uint256(call1Blocknumber), 1, type(uint128).max - 1));
        call2Blocknumber = uint128(bound(uint256(call2Blocknumber), call1Blocknumber + 1, type(uint128).max));
        call1Timestamp = uint128(bound(uint256(call1Timestamp), 1, type(uint128).max - 1));
        call2Timestamp = uint128(bound(uint256(call2Timestamp), call1Timestamp + 1, type(uint128).max));

        address caller = address(0x1234);
        vm.deal(caller, 20 ether);

        vm.roll(uint256(call1Blocknumber));
        vm.warp(uint256(call1Timestamp));
        vm.prank(caller);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "First fallback call must succeed on reference");

        vm.roll(uint256(call2Blocknumber));
        vm.warp(uint256(call2Timestamp));
        vm.prank(caller);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        assertTrue(ok2);
    }
}
